import unittest.mock as mock

from _pytest.compat import getfuncargnames
from _pytest.compat import num_mock_patch_args


class AmbiguousResult:
    def __bool__(self):
        raise ValueError("ambiguous truth value")


class AmbiguousArrayLike:
    def __eq__(self, other):
        return AmbiguousResult()


@mock.patch("os.getcwd")
def default_patch(fixture):
    pass


@mock.patch("os.getcwd", new=mock.DEFAULT)
def explicit_default(fixture):
    pass


@mock.patch("os.getcwd", new=AmbiguousArrayLike())
def explicit_new(fixture):
    pass


assert num_mock_patch_args(default_patch) == 1
assert getfuncargnames(default_patch) == ()
assert num_mock_patch_args(explicit_default) == 1
assert getfuncargnames(explicit_default) == ()
assert num_mock_patch_args(explicit_new) == 0
assert getfuncargnames(explicit_new) == ("fixture",)
print("edge cases OK")
